// =============================================================================
// GCP — JWT signing against real Cloud Logging
// =============================================================================

fn make_gcp_config() -> Option<GcpSourceConfig> {
    let project_id = env("GCP_PROJECT_ID")?;
    let key_path = env("GCP_SERVICE_ACCOUNT_KEY")?;

    // Verify key file exists
    if !std::path::Path::new(&key_path).exists() {
        eprintln!("GCP key file not found: {key_path}");
        return None;
    }

    Some(GcpSourceConfig {
        enabled: true,
        project_id: Some(project_id),
        service_account_key: Some(key_path),
        credential_secret: None,
        api_url_override: None,
        token_url_override: None,
        interval_secs: None,
        services: vec![GcpService {
            name: "cloud_logging".to_string(),
            config: HashMap::new(),
        }],
        topic: "test-gcp".to_string(),
        filter: None,
    })
}

#[tokio::test]
#[ignore = "requires live cloud credentials"]
async fn gcp_health_check() {
    load_env();
    let Some(config) = make_gcp_config() else {
        eprintln!("Skipping GCP: credentials not available");
        return;
    };
    let source = GcpSource::new(config);

    let healthy = source.health_check().await.expect("health_check failed");
    assert!(
        healthy,
        "GCP health check should pass with valid credentials"
    );
}

#[tokio::test]
#[ignore = "requires live cloud credentials"]
async fn gcp_fetch_cloud_logging() {
    load_env();
    let Some(config) = make_gcp_config() else {
        eprintln!("Skipping GCP: credentials not available");
        return;
    };
    let source = GcpSource::new(config);

    let results = source.fetch(None).await.expect("fetch failed");
    eprintln!(
        "GCP Cloud Logging: {} result(s), {} total records",
        results.len(),
        results.iter().map(|r| r.records.len()).sum::<usize>()
    );
}
